mapper.select:
SELECT ミーティング._ミーティング番号 as "meetingNumber.value", ミーティング.件名 as "subject.value", SQ_日程候補.最小開始日時 as "earliestStartDateTime.value", SQ_日程候補.最大終了日時 as "latestEndDateTime.value" FROM ミーティング._ミーティング AS ミーティング LEFT OUTER JOIN ミーティング._ミーティングメモ AS ミーティングメモ ON ミーティングメモ.ミーティング番号 = ミーティング._ミーティング番号 INNER JOIN ミーティング.主催者端末 AS 主催者端末 ON 主催者端末.ミーティング番号 = ミーティング._ミーティング番号 INNER JOIN ( SELECT ミーティング番号, MIN(開始日時) AS 最小開始日時, MAX(終了日時) AS 最大終了日時 FROM 日程候補._日程 WHERE 開始日時 <= #{endDateTime} AND 終了日時 >= #{startDateTime} GROUP BY ミーティング番号 ) AS SQ_日程候補 ON SQ_日程候補.ミーティング番号 = ミーティング._ミーティング番号 WHERE 主催者端末.IPアドレス = #{ipAddress.value} AND 主催者端末.OSファミリー = #{osFamily.value} AND 主催者端末.ユーザーエージェントファミリー = #{userAgentFamily.value}
AND (ミーティング.件名 LIKE #{keywordCondition} OR ミーティングメモ.メモ LIKE #{keywordCondition})
ORDER BY SQ_日程候補.最小開始日時, SQ_日程候補.最大終了日時, ミーティング.件名, ミーティング.登録日時 LIMIT 20
